const MODEL = process.env.LLM_MODEL || 'gpt-4o-mini';

async function classifyAssetWithOpenAI(text) {
  // Simple prompt-based classification. Uses the OpenAI HTTP API (chat completions style).
  const prompt = `Classify the following collateral asset description with JSON output containing assetType and eligibilityTier (A,B,C, or ineligible). Return ONLY a JSON object.\n\nDescription:\n${text}`;

  const res = await fetch('https://api.openai.com/v1/chat/completions', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${OPENAI_KEY}`
    },
    body: JSON.stringify({
      model: MODEL,
      messages: [{ role: 'system', content: 'You are a classifier that outputs JSON with assetType and eligibilityTier.' }, { role: 'user', content: prompt }],
      max_tokens: 150,
      temperature: 0
    })
  });
  if (!res.ok) throw new Error(`OpenAI error: ${res.status} ${res.statusText}`);
  const data = await res.json();
  const content = data.choices?.[0]?.message?.content || data.choices?.[0]?.text || '';
  // Extract JSON from content
  const match = content.match(/\{[\s\S]*\}/);
  if (!match) throw new Error('OpenAI returned no JSON');
  const json = JSON.parse(match[0]);
  return json;
}

